"""Temporary B1 offline probe: same-path budget admission over the real
structured -> free-text fallback, using the repository's actual
``invoke_structured_or_freetext`` / ``invoke_structured`` functions.

Runs OUTSIDE the repository. No network, no real provider. The fake provider is
reached only through a gateway wrapper placed on the ``get_llm()`` object.
"""

from __future__ import annotations

import sys
from dataclasses import dataclass, field

from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.messages import AIMessage
from langchain_core.outputs import ChatGeneration, ChatResult
from pydantic import BaseModel

# Use the repository's real fallback helpers unchanged.
from tradingagents.agents.structured import (
    bind_structured,
    invoke_structured_or_freetext,
)


class Report(BaseModel):
    summary: str


TEXT = "plain-text answer"


def _render(r: Report) -> str:  # render callback expected by the real helper
    return r.summary


# ---------------------------------------------------------------------------
# Fake provider: the receiver. It intentionally FAILS structured calls so the
# real fallback fires. First call = "structured", subsequent = "freetext".
# ---------------------------------------------------------------------------
class FakeProvider(BaseChatModel):
    received: list = field(default_factory=list)  # tags of every request it saw

    @property
    def _llm_type(self) -> str:
        return "fake-provider"

    def bind_tools(self, tools, **kwargs):
        return self.model_copy(update={})

    def with_structured_output(self, schema, **kwargs):
        # mimic a provider that supports it; the call itself will fail at runtime
        return _StructuredAdapter(self, schema)

    def _generate(self, messages, stop=None, run_manager=None, **kwargs) -> ChatResult:
        # The FIRST request is the structured one; it FAILS at the receiver.
        if not any(t == "structured" for t in self.received):
            self.received.append("structured")
            raise ValueError("provider refused structured output (simulated)")
        self.received.append("freetext")
        return ChatResult(generations=[ChatGeneration(message=AIMessage(content=TEXT))])


class _StructuredAdapter:
    """What ``with_structured_output`` returns: a callable runnable."""

    def __init__(self, provider: FakeProvider, schema):
        self.provider = provider
        self.schema = schema

    def invoke(self, prompt, config=None, **kwargs):
        assert self.provider is PROVIDER_SINGLETON, "adapter bypassed the gateway!"
        return self.provider.invoke(prompt)

"""Temporary B1 offline probe: same-path budget admission through the REAL
structured -> free-text fallback helper, with a gateway wrapper placed on the
``get_llm()`` object.

Runs OUTSIDE the repository. No network. No real provider.

Each group prepares N admissions at the gateway. The fake provider fails the
structured request at the receiver, so the real ``invoke_structured`` catches it
and the real helper falls back to ``plain_llm.invoke`` (a second admission).
"""

from __future__ import annotations

import sys
import traceback
from dataclasses import dataclass, field

from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.messages import AIMessage
from langchain_core.outputs import ChatGeneration, ChatResult
from pydantic import BaseModel

# The repository's actual fallback helpers, used UNCHANGED.
from tradingagents.agents.structured import invoke_structured_or_freetext


class Report(BaseModel):
    summary: str


TEXT = "plain-text answer"


# ---------------------------------------------------------------------------
# Fake provider = the receiver. It records every request it actually recvs and
# FAILS the first (structured) call so the real fallback fires.
# ---------------------------------------------------------------------------
class FakeProvider(BaseChatModel):
    received: list = field(default_factory=list)

    @property
    def _llm_type(self) -> str:
        return "fake-provider"

    def _generate(self, messages, stop=None, run_manager=None, **kwargs) -> ChatResult:
        if not self.received or self.received[-1] != "structured":
            self.received.append("structured")
            raise ValueError("provider refused structured output (simulated)")
        self.received.append("freetext")
        return ChatResult(generations=[ChatGeneration(message=AIMessage(content=TEXT))])


# ---------------------------------------------------------------------------
# Gateway: wraps the provider. This is the candidate single interception point.
# All model entry points go through ``_admit`` before reaching the provider.
# ---------------------------------------------------------------------------
class Gateway(BaseChatModel):
    provider: FakeProvider
    allow: int
    stats: dict = field(default_factory=dict)

    @property
    def _llm_type(self) -> str:
        return "gateway"

    def _init_stats(self):
        return {"admit_attempts": 0, "denied": 0, "received": 0}

    def _admit(self, kind: str):
        self.stats["admit_attempts"] += 1
        if self.stats["admit_attempts"] > self.allow:
            self.stats["denied"] += 1
            raise RuntimeError(f"BUDGET_DENIED: {kind} request refused at gateway")
        self.stats["received"] += 1

    def _generate(self, messages, stop=None, run_manager=None, **kwargs) -> ChatResult:
        self._admit("chat")
        return self.provider._generate(messages, stop=stop, run_manager=run_manager, **kwargs)

    # ---- the two derived entry points the fallback actually uses ----
    def with_structured_output(self, schema, **kwargs):
        outer = self

        class _Structured:
            def invoke(self, prompt, config=None, **kw):
                outer._admit("structured")
                return outer.provider.with_structured_output(schema).invoke(prompt)

        return _Structured()

    def bind_tools(self, tools, **kwargs):
        return self  # tool binding not exercised here

    def invoke(self, input, config=None, **kwargs):
        # LangChain BaseChatModel routes .invoke -> _generate; keep explicit for clarity
        return super().invoke(input, config=config, **kwargs)


def run_group(name: str, allow: int) -> dict:
    stats = {"admit_attempts": 0, "denied": 0, "received": 0}
    provider = FakeProvider()
    gw = Gateway(provider=provider, allow=allow, stats=stats)
    out = {"group": name, "allow": allow, "result": None, "exception": None}
    try:
        # Build the structured runnable exactly as an agent would.
        structured = gw.with_structured_output(Report)
        # Call the REAL helper: structured first, free-text fallback on failure.
        out["result"] = invoke_structured_or_freetext(
            structured, gw, "probe-prompt", lambda r: r.summary, "Probe"
        )
    except Exception as exc:  # noqa: BLE001 - we want to observe propagation
        out["exception"] = f"{type(exc).__name__}: {exc}"
        out["traceback_tail"] = traceback.format_exc(limit=2)
    out["gateway"] = dict(stats)
    out["provider_received"] = list(provider.received)
    return out


if __name__ == "__main__":
    groups = [
        run_group("allow=2 (structured + fallback both admitted)", allow=2),
        run_group("allow=1 (structured only; fallback denied)", allow=1),
        run_group("allow=0 (zero requests)", allow=0),
    ]
    print(f"python: {sys.executable}")
    for g in groups:
        print("\n=== " + g["group"] + " ===")
        print("  gateway admit_attempts :", g["gateway"]["admit_attempts"])
        print("  gateway denied         :", g["gateway"]["denied"])
        print("  fake provider received :", g["provider_received"], f'({len(g["provider_received"])} requests)')
        print("  returned               :", repr(g["result"]))
        print("  exception              :", g["exception"])
        if g.get("traceback_tail") and g["exception"]:
            print("  traceback tail:\n" + g["traceback_tail"])

