# calls : room for several calls (2 is enough to send a second one).
# cost  : room for several calls at the tiny per-call cost.
BUDGET_LIMITS: dict[str, Any] = {
    "max_total_tokens": 1000,
    "max_calls": 5,
    "max_cost_usd": "1.00",
}

# One call asks for 1000 tokens; that consumes the whole token axis.
FULL_TOKEN_CALL: dict[str, Any] = {
    "max_tokens": 1000,
    "max_calls": 1,
    "max_cost_usd": "0.01",
}

# A second call of the SAME size. On tokens alone it cannot fit after the first
# call holds all 1000 tokens; calls (1/5 used) and cost (0.01/1.00) are fine.
SECOND_FULL_TOKEN_CALL: dict[str, Any] = {
    "max_tokens": 1000,
    "max_calls": 1,
    "max_cost_usd": "0.01",
}

# --- Control run (same limits, low ACTUAL usage) ---------------------------
# Known low usage: the first call reserved 1000 tokens but actually used only 100.
# ``settle`` with actual usage 100 releases 900 back, leaving 900 free — so a
# 1000-token second call still cannot fit, but an 800-token call can. The control
# uses an 800-token second call to show the governor CAN grant once balance exists,
# which proves the denial in the main case is about the held 1000, not something
# else being exhausted.
LOW_KNOWN_USAGE: dict[str, Any] = {"tokens": 100}
SECOND_SMALL_CALL: dict[str, Any] = {
    "max_tokens": 800,
    "max_calls": 1,
    "max_cost_usd": "0.01",
}


def base_limits() -> dict[str, Any]:
